# -*- coding: utf-8 -*-
from pathlib import Path
import json,ast
import numpy as np
import pandas as pd
O=Path(r'.\EI_Reviewer1_Major6_Revision');M5=Path(r'.\EI_Reviewer1_Major5_Revision')
def main():
 assert (O/'cache/EXTRACTION_READY.json').exists();source=(O/'audit/survival_m5.py').read_text();tree=ast.parse(source);fn=next(q for q in tree.body if isinstance(q,ast.FunctionDef) and q.name=='estimates');env={'np':np};exec(compile(ast.Module(body=[fn],type_ignores=[]),'<unchanged M5 estimates>','exec'),env);estimate=env['estimates'];e=pd.read_parquet(O/'paired/CDH_Fixed_Original_Clean_Events.parquet');m=np.load(O/'cache/CDH_Event_Metrics.npy',mmap_mode='r');full=np.load(O/'cache/Full_Severity_ALL_2000_2024.npy',mmap_mode='r');q=100*np.searchsorted(full,e.climate_cumulative_severity.to_numpy(),side='right')/len(full);grp=np.where(q<90,0,1);year=e.Onset_Year.to_numpy();rows=[];details=[];NB=250
 # Native original full replay against accepted M5 records, including nonpositive damage.
 index=np.full(4796212,-1,np.int32);index[e.event_num.to_numpy(int)]=np.arange(len(e));check=np.zeros(4,np.int64)
 for f in sorted((M5/'event_records/CDH').glob('*.parquet')):
  old=pd.read_parquet(f,columns=['event_num','Followup_Days','Outcome_Code','Valid_Followup']);ix=index[old.event_num.to_numpy(int)];assert (ix>=0).all();check+=np.array([len(old),(m[ix,0,7]!=old.Followup_Days.to_numpy()).sum(),(m[ix,0,8]!=old.Outcome_Code.to_numpy()).sum(),(m[ix,0,9]!=old.Valid_Followup.to_numpy()).sum()])
 verification=dict(N_M5_Records=int(check[0]),Duration_Mismatch=int(check[1]),Reason_Mismatch=int(check[2]),Valid_Mismatch=int(check[3]));(O/'audit/M5_Native_Recovery_Reproduction.json').write_text(json.dumps(verification,indent=2),encoding='utf8');assert not check[1:].any(),verification
 for name,period,pop,a,b in [('LOYO','REF_2000_2020',year<=2020,1,2),('LOYO','OUT_2021_2024',year>=2021,1,2),('EARLY','APPLY_2011_2024',year>=2011,3,4)]:
  common=pop&(q>=75)&np.isfinite(m[:,a,0])&np.isfinite(m[:,b,0])&np.isfinite(m[:,a,6])&np.isfinite(m[:,b,6])&(m[:,a,9]==1)&(m[:,b,9]==1);idx=np.flatnonzero(common)
  for sc in [20,50]:
   blockmap=np.load(M5/'cache'/f'CDH_pixel_blocks_{sc}.npy',mmap_mode='r');B=int(blockmap.max()+1);blocks=blockmap[e.row.to_numpy(int)[idx],e.col.to_numpy(int)[idx]];assert (blocks>=0).all();W=np.random.default_rng(20261109+sc).multinomial(B,np.full(B,1/B),size=NB);allcounts=[];point=[];boots=[]
   for variant,k in [('ORIGINAL_COMMON_PHASE',a),(name,b)]:
    dur=m[idx,k,7].astype(int);reason=m[idx,k,8].astype(int);gr=grp[idx];flat=(((blocks*2+gr)*5+reason)*121+dur).astype(int);C=np.bincount(flat,minlength=B*2*5*121).reshape(B,2,5,121);allcounts.append(C);pt=estimate(C.sum(axis=0));boot=estimate((W@C.reshape(B,-1)).reshape(NB,2,5,121));point.append(pt);boots.append(boot)
    for gg,label in [(0,'High'),(1,'Extreme')]:
     records=C[:,gg].sum(axis=0);tot=records.sum();count=records.sum(axis=1);details.append(dict(Comparison=name,Period=period,Variant=variant,Block_km=sc,Group=label,N_Events=int(tot),N_Active_Blocks=int((C[:,gg].sum(axis=(1,2))>0).sum()),N_Risk120=float(pt['N_risk_120'][gg]),Recovered_N=int(count[0]),Next_Interrupted_N=int(count[1]),Administrative_N=int(count[2]+count[3]),Incomplete_N=int(count[4]),Censored_Fraction=float(count[1:].sum()/tot) if tot else np.nan,Next_Interruption_Fraction=float(count[1]/tot) if tot else np.nan))
    for key in ['P120','RMPT120','AJ_Recovery120','AJ_Next120']:
     for gg,label in [(0,'High'),(1,'Extreme'),(-1,'Extreme_minus_High')]:
      factor=100 if gg==-1 and key!='RMPT120' else 1;est=(pt[key][gg] if gg>=0 else pt[key][1]-pt[key][0])*factor;values=(boot[key][:,gg] if gg>=0 else boot[key][:,1]-boot[key][:,0])*factor;valid=np.isfinite(values);ci=np.quantile(values[valid],[.025,.975]) if valid.sum()>=200 and np.isfinite(est) else [np.nan,np.nan]
      rows.append(dict(Event='CDH',Comparison=name,Period=period,Variant=variant,Group_Or_Contrast=label,Metric=key,Estimate=est,CI_Lower=ci[0],CI_Upper=ci[1],Unit='days' if key=='RMPT120' else ('percentage_points' if gg==-1 else 'probability'),Bootstrap_Block_km=sc,Bootstrap_N=NB,Bootstrap_Valid=int(valid.sum()),N_Common_Events=len(idx),N_Whole_Blocks=B,N_Active_Blocks=len(np.unique(blocks)),N_Risk120=float(pt['N_risk_120'][gg]) if gg>=0 else np.nan,Endpoint_Status='NOT_ESTIMABLE' if not np.isfinite(est) else ('CI_NOT_ESTIMABLE' if not np.isfinite(ci).all() else 'ESTIMABLE_CONDITIONAL'),Group_ECDF_Reference='unchanged M5 full original CDH2000-2024 complete-event ECDF, not Task4 period ECDF',Rules='M5 PRIMARY postpeak/termination-origin120 inclusive/catalogue-next/2adjacent finite observations',Estimand='KM net recovery with interruption censoring' if key in ['P120','RMPT120'] else 'AJ observed competing-risk cumulative incidence',Limit='same event IDs, exact common phase support; whole spatial blocks sampled identically for versions/groups; estimates conditional on retained cohort, not ecological critical-point proof'))
   for key in ['P120','RMPT120','AJ_Recovery120']:
    factor=1 if key=='RMPT120' else 100;est=((point[1][key][1]-point[1][key][0])-(point[0][key][1]-point[0][key][0]))*factor;v=((boots[1][key][:,1]-boots[1][key][:,0])-(boots[0][key][:,1]-boots[0][key][:,0]))*factor;valid=np.isfinite(v);ci=np.quantile(v[valid],[.025,.975]) if valid.sum()>=200 and np.isfinite(est) else [np.nan,np.nan];rows.append(dict(Event='CDH',Comparison=name,Period=period,Variant='ALTERNATIVE_MINUS_ORIGINAL',Group_Or_Contrast='CHANGE_IN_Extreme_minus_High',Metric=key,Estimate=est,CI_Lower=ci[0],CI_Upper=ci[1],Unit='days' if key=='RMPT120' else 'percentage_points',Bootstrap_Block_km=sc,Bootstrap_N=NB,Bootstrap_Valid=int(valid.sum()),N_Common_Events=len(idx),N_Whole_Blocks=B,Endpoint_Status='ESTIMABLE_CONDITIONAL' if np.isfinite(ci).all() else 'NOT_ESTIMABLE',Limit='paired spatial-bootstrap difference of group contrasts; no subtraction of separate group CI endpoints'))
  print('RECOVERY',name,period,len(idx),'paired events',flush=True)
 pd.DataFrame(rows).to_csv(O/'M6_Recovery_Sensitivity.csv',index=False,encoding='utf-8-sig');pd.DataFrame(details).to_csv(O/'supplement/Recovery_Cohorts_And_Censoring.csv',index=False);(O/'cache/RECOVERY_READY.json').write_text(json.dumps(dict(Rows=len(rows),Bootstrap_N=NB,Scales_km=[20,50],Seed=20261109,Native_M5_Reproduction=verification),indent=2),encoding='utf8');print('RECOVERY COMPLETE',flush=True)
if __name__=='__main__':main()
